function LogIterator.new(sessionOrHandle)
    local self = setmetatable({}, LogIterator)
    if type(sessionOrHandle) == "table" then
        self.session = sessionOrHandle
        self.handle = sessionOrHandle.ptr
    else
        self.session = nil
